1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  *, *::before, *::after { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    padding: 48px 16px;
12	    font: 16px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
13	    color: #1f2328;
14	    background: #f6f7f9;
15	  }
16	  main {
17	    max-width: 520px;
18	    margin: 0 auto;
19	    background: #fff;
20	    border: 1px solid #e3e6ea;
21	    border-radius: 12px;
22	    padding: 24px;
23	  }
24	  h1 { margin: 0 0 16px; font-size: 24px; }
25	  form { display: flex; flex-wrap: wrap; gap: 8px; }
26	  form [data-testid="todo-input"] { flex-basis: 200px; }
27	  .due-input { flex: none; }
28	  select {
29	    flex: none;
30	    padding: 10px 12px;
31	    font: inherit;
32	    border: 1px solid #c9ced4;
33	    border-radius: 8px;
34	    background: #fff;
35	  }
36	  select:focus { outline: 2px solid #2f6feb; outline-offset: 1px; border-color: #2f6feb; }
37	  li[data-priority] { padding-left: 10px; padding-right: 6px; border-left: 4px solid; }
38	  li[data-priority="high"] { border-left-color: #d92d20; background: #fef3f2; }
39	  li[data-priority="med"] { border-left-color: #f79009; background: #fffaeb; }
40	  li[data-priority="low"] { border-left-color: #98a2b3; background: #f8f9fb; }
41	  .due { flex: none; font-size: 14px; color: #6a737d; white-space: nowrap; }
42	  li[data-overdue="true"] .due { color: #b42318; font-weight: 600; }
43	  input {
44	    flex: 1;
45	    min-width: 0;
46	    padding: 10px 12px;
47	    font: inherit;
48	    border: 1px solid #c9ced4;
49	    border-radius: 8px;
50	  }
51	  input:focus { outline: 2px solid #2f6feb; outline-offset: 1px; border-color: #2f6feb; }
52	  button {
53	    font: inherit;
54	    padding: 10px 16px;
55	    border: 0;
56	    border-radius: 8px;
57	    background: #2f6feb;
58	    color: #fff;
59	    cursor: pointer;
60	  }
61	  button:hover { background: #255ecc; }
62	  ul { list-style: none; margin: 16px 0 0; padding: 0; }
63	  li {
64	    display: flex;
65	    align-items: center;
66	    gap: 8px;
67	    padding: 10px 0;
68	    border-top: 1px solid #eef0f2;
69	  }
70	  li:first-child { border-top: 0; }
71	  .text { flex: 1; overflow-wrap: anywhere; }
72	  li[data-completed="true"] .text { color: #6a737d; text-decoration: line-through; }
73	  .toggle { flex: none; width: 18px; height: 18px; margin: 0; accent-color: #2f6feb; cursor: pointer; }
74	  .filters { display: flex; flex-wrap: wrap; gap: 4px; margin: 16px 0 0; }
75	  .filters button { background: transparent; color: #1f2328; padding: 6px 12px; border: 1px solid transparent; }
76	  .filters button:hover { background: #eef0f2; }
77	  .filters button[aria-pressed="true"] { border-color: #c9ced4; background: #f6f7f9; }
78	  .delete { background: transparent; color: #b42318; padding: 6px 10px; }
79	  .delete:hover { background: #fdecea; }
80	  .empty { margin: 16px 0 0; color: #6a737d; }
81	</style>
82	</head>
83	<body>
84	<main>
85	  <h1>Todos</h1>
86	  <form id="todo-form">
87	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
88	    <input data-testid="todo-due" class="due-input" type="date" aria-label="Due date (optional)">
89	    <select data-testid="todo-priority" aria-label="Priority">
90	      <option value="low">Low</option>
91	      <option value="med" selected>Medium</option>
92	      <option value="high">High</option>
93	    </select>
94	    <button data-testid="todo-add" type="submit">Add</button>
95	  </form>
96	  <div class="filters" id="filters" role="group" aria-label="Show">
97	    <button data-testid="filter-all" data-filter="all" type="button" aria-pressed="true">All</button>
98	    <button data-testid="filter-active" data-filter="active" type="button" aria-pressed="false">Active</button>
99	    <button data-testid="filter-completed" data-filter="completed" type="button" aria-pressed="false">Completed</button>
100	  </div>
101	  <ul data-testid="todo-list" id="todo-list"></ul>
102	  <p class="empty" id="empty">Nothing here yet. Add your first todo above.</p>
103	</main>
104	<script src="todos.js"></script>
105	<script>
106	  var STORAGE_KEY = 'todos';
107	
108	  function makeId() {
109	    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
110	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
111	  }
112	
113	  function load() {
114	    try {
115	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
116	      return Array.isArray(data) ? data : [];
117	    } catch (e) {
118	      return [];
119	    }
120	  }
121	
122	  function save(todos) {
123	    try {
124	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
125	    } catch (e) {}
126	  }
127	
128	  var todos = load();
129	  var form = document.getElementById('todo-form');
130	  var input = form.querySelector('[data-testid="todo-input"]');
131	  var list = document.getElementById('todo-list');
132	  var empty = document.getElementById('empty');
133	  var dueInput = form.querySelector('[data-testid="todo-due"]');
134	  var priorityInput = form.querySelector('[data-testid="todo-priority"]');
135	  var filterButtons = document.querySelectorAll('#filters [data-filter]');
136	  var filter = 'all';
137	  var EMPTY_TEXT = {
138	    none: 'Nothing here yet. Add your first todo above.',
139	    active: 'All done. Nothing left to do.',
140	    completed: 'Nothing completed yet.'
141	  };
142	
143	  Array.prototype.forEach.call(filterButtons, function (button) {
144	    button.addEventListener('click', function () {
145	      filter = button.dataset.filter;
146	      render();
147	    });
148	  });
149	
150	  // Shows a stored "YYYY-MM-DD" as a local date, built from its parts so no UTC shift applies.
151	  function formatDue(due) {
152	    var parts = due.split('-');
153	    var date = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
154	    return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
155	  }
156	
157	  function render() {
158	    var today = localDateString(new Date());
159	    Array.prototype.forEach.call(filterButtons, function (button) {
160	      button.setAttribute('aria-pressed', String(button.dataset.filter === filter));
161	    });
162	
163	    list.textContent = '';
164	    var shown = visibleTodos(todos, filter);
165	    shown.forEach(function (todo) {
166	      var completed = !!todo.completed;
167	      var li = document.createElement('li');
168	      li.setAttribute('data-testid', 'todo-item');
169	      li.setAttribute('data-completed', String(completed));
170	      var overdue = isOverdue(todo.due, today);
171	      li.setAttribute('data-overdue', String(overdue));
172	      li.setAttribute('data-priority', normalizePriority(todo.priority));
173	      li.dataset.id = todo.id;
174	
175	      var toggle = document.createElement('input');
176	      toggle.type = 'checkbox';
177	      toggle.className = 'toggle';
178	      toggle.setAttribute('data-testid', 'todo-toggle');
179	      toggle.setAttribute('aria-label', 'Mark "' + todo.text + '" as ' + (completed ? 'not done' : 'done'));
180	      toggle.checked = completed;
181	      toggle.addEventListener('change', function () {
182	        todos = todos.map(function (t) {
183	          return t.id === todo.id ? Object.assign({}, t, { completed: toggle.checked }) : t;
184	        });
185	        save(todos);
186	        render();
187	      });
188	
189	      var text = document.createElement('span');
190	      text.className = 'text';
191	      text.setAttribute('data-testid', 'todo-text');
192	      text.textContent = todo.text;
193	
194	      var del = document.createElement('button');
195	      del.type = 'button';
196	      del.className = 'delete';
197	      del.setAttribute('data-testid', 'todo-delete');
198	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
199	      del.textContent = 'Delete';
200	      del.addEventListener('click', function () {
201	        todos = todos.filter(function (t) { return t.id !== todo.id; });
202	        save(todos);
203	        render();
204	      });
205	
206	      li.appendChild(toggle);
207	      li.appendChild(text);
208	      if (typeof todo.due === 'string' && DUE_PATTERN.test(todo.due)) {
209	        var due = document.createElement('span');
210	        due.className = 'due';
211	        due.setAttribute('data-testid', 'todo-due-date');
212	        due.textContent = (overdue ? 'Overdue · ' : 'Due ') + formatDue(todo.due);
213	        li.appendChild(due);
214	      }
215	      li.appendChild(del);
216	      list.appendChild(li);
217	    });
218	    empty.textContent = todos.length === 0 ? EMPTY_TEXT.none : (EMPTY_TEXT[filter] || '');
219	    empty.hidden = shown.length > 0;
220	  }
221	
222	  form.addEventListener('submit', function (event) {
223	    event.preventDefault();
224	    var value = input.value.trim();
225	    if (!value) return;
226	    var todo = { id: makeId(), text: value, createdAt: Date.now(), completed: false, priority: normalizePriority(priorityInput.value) };
227	    if (DUE_PATTERN.test(dueInput.value)) todo.due = dueInput.value;
228	    todos.push(todo);
229	    save(todos);
230	    input.value = '';
231	    dueInput.value = '';
232	    priorityInput.value = 'med';
233	    input.focus();
234	    render();
235	  });
236	
237	  // Today may have changed while the tab was hidden (e.g. overnight).
238	  document.addEventListener('visibilitychange', function () {
239	    if (!document.hidden) render();
240	  });
241	
242	  render();
243	</script>
244	</body>
245	</html>
